css:
@import url("https://fonts.googleapis.com/css2?family=Petrona:ital,wght@0,500;0,700;1,500&family=Golos+Text:wght@400;500;600&display=swap");
:root{--bt:#8A1F4B;--bt2:#6E1639;--lf:#5E8C31;--lf2:#476B24;--mw:#F1F6EC;--ink:#232B1E;--gr:#5A6353;--ln:#DCE5D3;--wt:#3A8FD1;--h:"Petrona",Georgia,serif;--b:"Golos Text",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:700;margin:0;line-height:1.1}
.wrap{max-width:1160px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--bt);color:#fff;padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--lf);outline-offset:2px}
.nav{display:flex;justify-content:space-between;align-items:center;height:82px;position:relative}.logo{font-family:var(--h);font-size:26px;font-weight:700;text-decoration:none;color:var(--bt);display:flex;gap:8px;align-items:center}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0;font-weight:500;align-items:center}.menu a{text-decoration:none}.menu a:hover{color:var(--bt)}.menu .cta{background:var(--bt);color:#fff;padding:10px 18px;border-radius:30px}.menu .cta:hover{color:#fff;background:var(--bt2)}
.burger{display:none;background:none;border:2px solid var(--bt);color:var(--bt);width:44px;height:40px;border-radius:10px;font-size:20px;cursor:pointer}
.hero{background:var(--mw);border-radius:0 0 60px 60px;padding:50px 0 80px}.hero .wrap{display:grid;grid-template-columns:1.1fr .9fr;gap:50px;align-items:center}
.hero h1{font-size:clamp(42px,5.4vw,72px);color:var(--ink)}.hero h1 i{color:var(--bt);font-weight:500}
.hero p{font-size:19px;color:var(--gr);margin:22px 0 28px;max-width:30em}
.btn{display:inline-block;background:var(--bt);color:#fff;text-decoration:none;font:600 16px var(--b);padding:14px 26px;border-radius:30px;border:0;cursor:pointer}.btn.g{background:var(--lf2)}.btn.l{background:transparent;color:var(--ink);box-shadow:inset 0 0 0 2px var(--ln)}
.row{display:flex;flex-wrap:wrap;gap:12px}
.plate{position:relative}.plate img{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:50%;border:14px solid #fff;box-shadow:0 30px 60px rgba(35,43,30,.15)}
.tag{position:absolute;background:#fff;border-radius:40px;padding:10px 16px;font-weight:600;font-size:15px;box-shadow:0 10px 24px rgba(35,43,30,.12);display:flex;gap:8px;align-items:center}
.tag.a{top:8%;left:-6%}.tag.b{bottom:12%;right:-4%}.tag i{width:10px;height:10px;border-radius:50%;background:var(--lf);display:inline-block}.tag.b i{background:var(--bt)}
.cred{display:flex;flex-wrap:wrap;gap:10px 26px;font-size:15px;color:var(--gr)}.cred b{color:var(--ink)}
section{padding:86px 0}.sh{max-width:640px;margin-bottom:34px}.sh h2{font-size:clamp(34px,4.4vw,52px)}.sh p{color:var(--gr);margin:12px 0 0;font-size:18px}
.svc{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}
.sv{border:2px solid var(--ln);border-radius:24px;padding:24px}.sv svg{margin-bottom:12px}.sv h3{font-size:23px}.sv p{color:var(--gr);font-size:16px;margin:8px 0 0}
.plans{background:var(--mw)}
.len{display:inline-flex;background:#fff;border-radius:30px;padding:4px;margin-bottom:28px;flex-wrap:wrap}.len button{font:600 15px var(--b);background:transparent;border:0;border-radius:30px;padding:9px 18px;cursor:pointer;color:var(--ink)}.len button[aria-pressed=true]{background:var(--lf2);color:#fff}
.pg{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;align-items:stretch}
.pl{background:#fff;border-radius:26px;padding:30px;display:flex;flex-direction:column}.pl.star{background:var(--bt);color:#fff}
.pl h3{font-size:28px}.pl .who{color:var(--gr);font-size:15px;margin:4px 0 16px}.pl.star .who{color:#F3C6D6}
.pl .pr{font-family:var(--h);font-size:52px;font-weight:700;line-height:1}.pl .pr small{font:500 16px var(--b)}.pl .wk{font-size:15px;color:var(--gr);margin:6px 0 18px}.pl.star .wk{color:#F3C6D6}
.pl ul{list-style:none;padding:0;margin:0 0 24px;flex:1}.pl li{padding:8px 0 8px 28px;position:relative;border-top:1px solid var(--ln)}.pl.star li{border-color:rgba(255,255,255,.18)}
.pl li:before{content:"";position:absolute;left:4px;top:15px;width:12px;height:7px;border-left:2px solid var(--lf);border-bottom:2px solid var(--lf);transform:rotate(-45deg)}.pl.star li:before{border-color:#fff}
.pl.star .btn{background:#fff;color:var(--bt)}
.water .wrap{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.wf{background:#fff;border:2px solid var(--ln);border-radius:26px;padding:28px}
.wf label,.lb{display:block;font-weight:600;font-size:15px;margin-bottom:6px}.wf input[type=number],.wf select{width:100%;font:17px var(--b);padding:12px;border:2px solid var(--ln);border-radius:12px;margin-bottom:16px;color:var(--ink);background:#fff}
.fr{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fr>div{min-width:0}
.seg{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}.seg button{font:500 15px var(--b);border:2px solid var(--ln);background:#fff;border-radius:30px;padding:8px 14px;cursor:pointer;color:var(--ink)}.seg button[aria-pressed=true]{border-color:var(--wt);background:#E6F2FB}
.out{display:flex;align-items:center;gap:24px;flex-wrap:wrap}.out b{font-family:var(--h);font-size:64px;line-height:1;color:var(--wt)}.out p{margin:0;color:var(--gr)}
.glasses{display:flex;flex-wrap:wrap;gap:6px;margin-top:18px}.glasses span{width:24px;height:32px;border:2px solid var(--wt);border-top:0;border-radius:0 0 6px 6px;position:relative;overflow:hidden}
.glasses span i{position:absolute;left:0;right:0;bottom:0;background:var(--wt);opacity:.7}
.book{background:var(--ink);color:#EEF3E8}.book .wrap{display:grid;grid-template-columns:.9fr 1.1fr;gap:50px}.book .sh p{color:#B9C4AE}
.book form{background:#fff;color:var(--ink);border-radius:26px;padding:30px}.book input,.book select,.book textarea{width:100%;font:16px var(--b);padding:12px;border:2px solid var(--ln);border-radius:12px;margin-bottom:14px;color:var(--ink);background:#fff}.book label{display:block;font-weight:600;font-size:15px;margin-bottom:6px}
.msg{visibility:hidden;margin:12px 0 0;font-weight:600;color:var(--lf2)}.msg.on{visibility:visible}
.q{font-family:var(--h);font-style:italic;font-size:22px;line-height:1.45;margin:28px 0 8px}.qn{color:#B9C4AE;font-size:15px}
footer{padding:30px 0;font-size:15px;color:var(--gr)}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hero .wrap,.water .wrap,.book .wrap{grid-template-columns:1fr}.svc{grid-template-columns:1fr 1fr}.pg{grid-template-columns:1fr}.plate{max-width:420px;margin:0 auto}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:82px;left:0;right:0;background:#fff;flex-direction:column;align-items:flex-start;padding:18px 22px;z-index:30;box-shadow:0 10px 20px rgba(0,0,0,.06)}.menu.open{display:flex}.svc{grid-template-columns:1fr}.fr{grid-template-columns:1fr}.tag.a{left:0}.tag.b{right:0}.hero{border-radius:0 0 34px 34px}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const P=[["Starter","For getting back on track",29,["Weekly meal plan with 3 meals and 2 snacks","Shopping list for each week","Email check-in every 2 weeks"]],["Guided","Most popular",45,["Everything in Starter","Fortnightly 30-minute video review","Plan updated as you go","Message me any weekday"],1],["Complete","For medical or sport goals",65,["Everything in Guided","Weekly video review","Blood test and symptom tracking","Letter to your GP"]]];
let wk=8,sel='Guided';
function plans(){$('pg').innerHTML=P.map(p=>{const disc=wk===12?.85:wk===8?.92:1,per=Math.round(p[2]*disc),tot=per*wk;return`<div class="pl${p[4]?' star':''}"><h3>${p[0]}</h3><p class="who">${p[1]}</p><div class="pr">$${tot}<small> total</small></div><p class="wk">$${per} a week for ${wk} weeks${disc<1?`, you save $${p[2]*wk-tot}`:''}</p><ul>${p[3].map(x=>`<li>${x}</li>`).join('')}</ul><a class="btn g" href="#book" data-p="${p[0]}">Choose ${p[0]}</a></div>`}).join('');$('bp').value=`${sel}, ${wk} weeks`}
document.querySelector('.len').onclick=e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('.len button').forEach(x=>x.setAttribute('aria-pressed',x===b));wk=+b.dataset.w;plans()};
$('pg').addEventListener('click',e=>{const a=e.target.closest('[data-p]');if(!a)return;sel=a.dataset.p;$('bp').value=`${sel}, ${wk} weeks`});plans();
let cl=.25;function water(){const kg=Math.min(200,Math.max(30,+$('kg').value||0)),ex=Math.max(0,+$('ex').value||0);const l=kg*.033+ex/30*.35+cl;const g=Math.round(l/.25);
$('lt').textContent=l.toFixed(1)+' L';$('gl').textContent=`About ${g} glasses of 250 ml a day`;$('gls').innerHTML=Array.from({length:Math.ceil(g)},(_,i)=>`<span><i style="height:${i<g?80:0}%"></i></span>`).join('')}
['kg','ex'].forEach(i=>$(i).addEventListener('input',water));$('cli').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('cli').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));cl=+b.dataset.c;water()};$('wf').onsubmit=e=>e.preventDefault();water();
$('bf').onsubmit=e=>{e.preventDefault();$('msg').textContent=`Thanks ${$('bn').value}. I'll email you within one working day with times for your consult.`;$('msg').classList.add('on')};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
